import java.io.*;
import java.util.*;

public class codeforces {

    public static int computeMaxNonSpecial(char[] s, int n) {
        int max = 0;
        int current = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == '_' || s[i] == '(') {
                current = 0;
            } else {
                current++;
                max = Math.max(max, current);
            }
        }
        return max;
    }

    public static int countValidParenthesizedGroups(char[] s, int n) {
        int count = 0;
        int depth = 0;
        int lastOpen = -1;
        for (int i = 0; i < n; i++) {
            if (s[i] == '(') {
                if (depth == 0) lastOpen = i;
                depth++;
            } else if (s[i] == ')') {
                depth--;
                if (depth == 0 && lastOpen >= 0) {
                    boolean hasNonSpecial = false;
                    for (int j = lastOpen + 1; j < i; j++) {
                        if (s[j] != '_' && s[j] != '(') {
                            hasNonSpecial = true;
                            break;
                        }
                    }
                    if (hasNonSpecial) count++;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        int n = Reader.nextInt();
        String x = Reader.next();
        char[] ch = x.toCharArray();

        int maxVal = computeMaxNonSpecial(ch, n);
        int countw = countValidParenthesizedGroups(ch, n);

        System.out.println(maxVal + " " + countw);
    }
}

class Reader {
    static BufferedReader reader;
    static StringTokenizer tokenizer;

    static void init(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = new StringTokenizer("");
    }

    static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}
